CREATE VIRTUAL TABLE ug_artists_fts USING fts5(
  artist_key, content='ug_artists', content_rowid='id', tokenize='unicode61', detail='none'
)

CREATE VIRTUAL TABLE ug_index_fts USING fts5(
  artist_key, song_key, content='ug_index', content_rowid='tab_id', tokenize='unicode61', detail='none', columnsize=0
)

CREATE VIRTUAL TABLE ug_keys_fts USING fts5(
  key, content='ug_keys', content_rowid='id', tokenize='trigram', detail='none'
)

CREATE TRIGGER ug_artists_indexed AFTER INSERT ON ug_artists BEGIN
  INSERT INTO ug_artists_fts(rowid, artist_key) VALUES (new.id, new.artist_key);
END

CREATE TRIGGER ug_artists_unindexed AFTER DELETE ON ug_artists BEGIN
  INSERT INTO ug_artists_fts(ug_artists_fts, rowid, artist_key) VALUES ('delete', old.id, old.artist_key);
END

CREATE TRIGGER ug_index_fts_added AFTER INSERT ON ug_index BEGIN
  INSERT INTO ug_index_fts(rowid, artist_key, song_key) VALUES (new.tab_id, new.artist_key, new.song_key);
END

CREATE TRIGGER ug_index_fts_changed AFTER UPDATE OF artist_key, song_key ON ug_index
WHEN new.artist_key IS NOT old.artist_key OR new.song_key IS NOT old.song_key BEGIN
  INSERT INTO ug_index_fts(ug_index_fts, rowid, artist_key, song_key)
  VALUES ('delete', old.tab_id, old.artist_key, old.song_key);
  INSERT INTO ug_index_fts(rowid, artist_key, song_key) VALUES (new.tab_id, new.artist_key, new.song_key);
END

CREATE TRIGGER ug_index_keys_added AFTER INSERT ON ug_index BEGIN
  INSERT INTO ug_keys(key) SELECT new.artist_key WHERE NOT EXISTS (SELECT 1 FROM ug_keys WHERE key = new.artist_key);
  INSERT INTO ug_keys(key) SELECT new.song_key WHERE NOT EXISTS (SELECT 1 FROM ug_keys WHERE key = new.song_key);
END

CREATE TRIGGER ug_index_keys_changed AFTER UPDATE OF artist_key, song_key ON ug_index
WHEN new.artist_key IS NOT old.artist_key OR new.song_key IS NOT old.song_key BEGIN
  INSERT INTO ug_keys(key) SELECT new.artist_key WHERE NOT EXISTS (SELECT 1 FROM ug_keys WHERE key = new.artist_key);
  INSERT INTO ug_keys(key) SELECT new.song_key WHERE NOT EXISTS (SELECT 1 FROM ug_keys WHERE key = new.song_key);
END

CREATE TRIGGER ug_keys_indexed AFTER INSERT ON ug_keys BEGIN
  INSERT INTO ug_keys_fts(rowid, key) VALUES (new.id, new.key);
END
